import React from "react";
import { useVideoConfig, AbsoluteFill, useCurrentFrame, interpolate } from '../remotionShim';


export type PregnancyVlogIntroProps = Record<string, any>;

const PregnancyVlogIntro: React.FC<PregnancyVlogIntroProps> = ({
  backgroundColor = "#F4EFEA",
  transparentBackground = false,
  durationInSeconds = 8,
  chalkColor = "#E1526E",
}) => {
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  // Color transparent formatting logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Chalk boiling animation effect
  const boilFrame = Math.floor(frame / 3);
  const turbulenceSeed = boilFrame % 100;

  // Dynamic chalk circle sizing
  const rx = width * 0.43;
  const ry = height * 0.39;

  // Function to generate organic hand-drawn ellipse paths
  const getHandDrawnEllipsePath = (
    cx: number,
    cy: number,
    rxVal: number,
    ryVal: number,
    startAngleOffset: number,
    overshoot: number
  ) => {
    const points = [];
    const steps = 12;
    for (let i = 0; i <= steps; i++) {
      const angle = (i / steps) * Math.PI * 2 + startAngleOffset;
      const wobble = Math.sin(i * 2.3) * (Math.min(width, height) * 0.007);
      const currRx = rxVal + wobble;
      const currRy = ryVal + wobble;
      const x = cx + Math.cos(angle) * currRx;
      const y = cy + Math.sin(angle) * currRy;
      points.push({ x, y });
    }
    // Add realistic sketchy overshoot
    const finalAngle = Math.PI * 2 + startAngleOffset + overshoot;
    const xEnd = cx + Math.cos(finalAngle) * (rxVal + 5);
    const yEnd = cy + Math.sin(finalAngle) * (ryVal - 8);
    points.push({ x: xEnd, y: yEnd });

    let d = `M ${points[0].x.toFixed(1)} ${points[0].y.toFixed(1)}`;
    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];
      const xc = (prev.x + curr.x) / 2;
      const yc = (prev.y + curr.y) / 2;
      d += ` Q ${prev.x.toFixed(1)} ${prev.y.toFixed(1)} ${xc.toFixed(1)} ${yc.toFixed(1)}`;
    }
    return d;
  };

  // Generate 3 distinct paths for a multi-layered drawn chalk loop
  const path1 = getHandDrawnEllipsePath(width / 2 - 5, height / 2 + 8, rx, ry, -Math.PI / 2, 0.3);
  const path2 = getHandDrawnEllipsePath(width / 2 + 8, height / 2 - 6, rx * 1.01, ry * 0.98, -Math.PI / 2 + 0.4, 0.4);
  const path3 = getHandDrawnEllipsePath(width / 2 - 10, height / 2 + 4, rx * 0.98, ry * 1.02, -Math.PI / 2 - 0.2, 0.5);

  // Dynamic progress timing for each circling draw-in (sped up for faster formation)
  const circle1Progress = interpolate(frame, [5, 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const circle2Progress = interpolate(frame, [11, 24], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const circle3Progress = interpolate(frame, [17, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate offsets based on pathLength set to 100
  const offset1 = interpolate(circle1Progress, [0, 1], [100, 0]);
  const offset2 = interpolate(circle2Progress, [0, 1], [100, 0]);
  const offset3 = interpolate(circle3Progress, [0, 1], [100, 0]);

  // Subtle natural camera dynamic swing
  const rotationAngle = interpolate(frame, [0, durationInSeconds * 30], [-1.5, 1.5]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Dynamic Chalk Sketching Layer */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          zIndex: 10,
          transform: `rotate(${rotationAngle}deg)`,
        }}
      >
        <defs>
          <filter id="chalk-filter" x="-10%" y="-10%" width="120%" height="120%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.09"
              numOctaves="4"
              result="noise"
              seed={turbulenceSeed}
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="noise"
              scale={12}
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>

        {/* Chalk Circle Loop 1 */}
        <path
          d={path1}
          fill="none"
          stroke={chalkColor}
          strokeWidth={Math.min(width, height) * 0.025}
          strokeLinecap="round"
          filter="url(#chalk-filter)"
          pathLength={100}
          strokeDasharray={100}
          strokeDashoffset={offset1}
          style={{ opacity: circle1Progress > 0.01 ? 0.85 : 0 }}
        />

        {/* Chalk Circle Loop 2 */}
        <path
          d={path2}
          fill="none"
          stroke={chalkColor}
          strokeWidth={Math.min(width, height) * 0.018}
          strokeLinecap="round"
          filter="url(#chalk-filter)"
          pathLength={100}
          strokeDasharray={100}
          strokeDashoffset={offset2}
          style={{ opacity: circle2Progress > 0.01 ? 0.75 : 0 }}
        />

        {/* Chalk Circle Loop 3 */}
        <path
          d={path3}
          fill="none"
          stroke={chalkColor}
          strokeWidth={Math.min(width, height) * 0.022}
          strokeLinecap="round"
          filter="url(#chalk-filter)"
          pathLength={100}
          strokeDasharray={100}
          strokeDashoffset={offset3}
          style={{ opacity: circle3Progress > 0.01 ? 0.8 : 0 }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default PregnancyVlogIntro;